import java.util.Scanner;

public class Main {
    static final long MAX_LIMIT = 1000000 + 100000;
    static final long MOD_VALUE = 1000000007;
    static long k_value, p_value;
    static int count;
    static long answer;
    static int[] visited_flags = new int[(int) MAX_LIMIT];
    static int[] stored_vals = new int[(int) MAX_LIMIT];

    static void adjust(long[] x) {
        x[0] = ((x[0] % MOD_VALUE) + MOD_VALUE) % MOD_VALUE;
    }

    static void bfs(int start) {
        count++;
        int origin = start;
        long weight = 1;
        do {
            visited_flags[start] = 1;
            start = (int)((start * k_value) % p_value);
            weight = (weight * k_value) % p_value;
        } while (start != origin);
        long[] answerArr = {answer};
        if (weight == 1) {
            answerArr[0] = (answerArr[0] * p_value) % MOD_VALUE;
        }
        answer = answerArr[0];
    }

    static void solve() {
        if (k_value == 0) {
            long product = 1;
            for (int i = 1; i <= p_value - 1; i++) {
                product = (product * p_value) % MOD_VALUE;
            }
            System.out.println(product);
            return;
        }
        answer = 1;
        for (int i = 0; i <= p_value - 1; i++) {
            if (visited_flags[i] == 0) {
                bfs(i);
            }
        }
        System.out.println(answer);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        p_value = scanner.nextLong();
        k_value = scanner.nextLong();
        solve();
        scanner.close();
    }
}
